UPDATE eval_record
SET eval_weight = CASE id

        WHEN #{r.id} THEN #{r.evalWeight}

    END,
    is_excluded = CASE id

        WHEN #{r.id} THEN #{r.isExcluded}

    END
WHERE id IN

    #{r.id}

mapper.select:
SELECT r.teacher_id, u.real_name, ti.department, ti.title, ROUND( SUM(CASE WHEN r.is_excluded = 0 OR r.is_excluded IS NULL THEN r.total_score * COALESCE(r.eval_weight, 1) ELSE 0 END) / NULLIF(SUM(CASE WHEN r.is_excluded = 0 OR r.is_excluded IS NULL THEN COALESCE(r.eval_weight, 1) ELSE 0 END), 0) , 2) AS avg_score, SUM(CASE WHEN r.is_excluded = 0 OR r.is_excluded IS NULL THEN 1 ELSE 0 END) AS eval_count, SUM(CASE WHEN r.is_excluded = 1 THEN 1 ELSE 0 END) AS excluded_count, ROUND( SUM(CASE WHEN r.is_excluded = 0 OR r.is_excluded IS NULL THEN r.choice_score * COALESCE(r.eval_weight, 1) ELSE 0 END) / NULLIF(SUM(CASE WHEN r.is_excluded = 0 OR r.is_excluded IS NULL THEN COALESCE(r.eval_weight, 1) ELSE 0 END), 0) , 2) AS avg_choice_score, ROUND( SUM(CASE WHEN r.is_excluded = 0 OR r.is_excluded IS NULL THEN r.essay_score * COALESCE(r.eval_weight, 1) ELSE 0 END) / NULLIF(SUM(CASE WHEN r.is_excluded = 0 OR r.is_excluded IS NULL THEN COALESCE(r.eval_weight, 1) ELSE 0 END), 0) , 2) AS avg_essay_score FROM eval_record r JOIN sys_user u ON u.id = r.teacher_id JOIN teacher_info ti ON ti.user_id = r.teacher_id WHERE r.status = 1
AND r.semester_id = #{semesterId}
GROUP BY r.teacher_id, u.real_name, ti.department, ti.title ORDER BY avg_score DESC
